"""Public API used by relay servers."""
import base64
import binascii
import hashlib
import json
import math
import re
from datetime import datetime, timedelta

from flask import Blueprint, current_app, g, jsonify, request, send_from_directory
from sqlalchemy.exc import IntegrityError

from .auth import relay_required, verify_ed25519
from .models import Checkin, Setting, Collaborator, db, tz_from_name, utcnow

api_bp = Blueprint("api", __name__)

# Check-in IDs are UUIDs generated by the relay; they are also the snapshot file names
UUID_RE = re.compile(r"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$")
JPEG_MAGIC = b"\xff\xd8\xff"

# Fields of a check-in signed by the relay when it was made (same list on the relay, relay/crypto.py)
CHECKIN_FIELDS = ("uuid", "seq", "relay_id", "collaborator_id", "direction", "ts", "status", "reason", "distance",
                  "timezone", "snapshot_sha256")


def checkin_message(record: dict) -> bytes:
    """Same as the relay (relay/crypto.py): "location" is signed only when present (older check-ins
    and relay versions have none)."""
    fields = {k: record.get(k) for k in CHECKIN_FIELDS}
    if record.get("location") is not None:
        fields["location"] = record["location"]
    return b"in-Time checkin v2\n" + json.dumps(fields, sort_keys=True, separators=(",", ":")).encode()


def _signed_record(item: dict, relay_id: str) -> dict:
    """The check-in as the relay signed it (values exactly as received)."""
    return {"uuid": item.get("uuid"), "seq": item.get("seq"), "relay_id": relay_id, "collaborator_id": item.get("collaborator_id"),
            "direction": item.get("direction"), "ts": item.get("timestamp"), "status": item.get("status"),
            "reason": item.get("reason"), "distance": item.get("distance"), "timezone": item.get("timezone"),
            "snapshot_sha256": item.get("snapshot_sha256"), "location": item.get("location")}


# The phone's GPS accuracy (metres) is given the benefit of the doubt up to this value: a check-in
# is "outside" only when even the edge of its accuracy circle is beyond the area. Capped, so a
# huge reported accuracy can't hide a check-in made far away.
AREA_ACCURACY_ALLOWANCE_M = 100.0


def haversine_m(lat1, lng1, lat2, lng2) -> float:
    r = 6371008.8  # mean Earth radius (m)
    p1, p2 = math.radians(lat1), math.radians(lat2)
    dp, dl = p2 - p1, math.radians(lng2 - lng1)
    a = math.sin(dp / 2) ** 2 + math.cos(p1) * math.cos(p2) * math.sin(dl / 2) ** 2
    return 2 * r * math.asin(min(1.0, math.sqrt(a)))


def _location(value):
    """(lat, lng, accuracy) from the signed "location", None when the relay sent none."""
    if value is None:
        return None
    if not isinstance(value, dict):
        raise ValueError("bad location")
    lat, lng, acc = float(value["lat"]), float(value["lng"]), float(value.get("accuracy") or 0)
    if not (-90 <= lat <= 90 and -180 <= lng <= 180 and 0 <= acc < 1e6):  # also rejects NaN
        raise ValueError("bad location")
    return lat, lng, acc


def area_check(relay, loc):
    """("inside" | "outside" | "no_location" | None, distance from the area's centre in metres)."""
    if not relay.has_area:
        return None, None
    if loc is None:
        return "no_location", None
    lat, lng, acc = loc
    dist = haversine_m(relay.area_lat, relay.area_lng, lat, lng)
    outside = dist - min(acc, AREA_ACCURACY_ALLOWANCE_M) > relay.area_radius
    return ("outside" if outside else "inside"), round(dist, 1)


def effective_settings(relay):
    return {
        "max_in_time": relay.max_in_time or Setting.get("max_in_time"),
        "min_out_time": relay.min_out_time or Setting.get("min_out_time"),
    }


def _hm(value: str):
    h, m = value.split(":")
    return int(h), int(m)


def evaluate(direction: str, local: datetime, settings: dict):
    """(status, reason) computed here from the time and the site settings, never taken from the relay."""
    now_hm = (local.hour, local.minute)
    if direction == "IN" and now_hm > _hm(settings["max_in_time"]):
        return "KO", "late"
    if direction == "OUT" and now_hm < _hm(settings["min_out_time"]):
        return "KO", "early"
    return "OK", None


@api_bp.get("/ping")
@relay_required
def ping():
    return jsonify(ok=True, relay=g.relay.name, server_time=utcnow().isoformat())


@api_bp.get("/settings")
@relay_required
def settings():
    data = effective_settings(g.relay)
    # Minimum face similarity: the relay never uses a lower value than this one
    data["min_similarity"] = current_app.config["FACE_MIN_SIMILARITY"]
    if g.relay.timezone:
        data["timezone"] = g.relay.timezone
    return jsonify(data)


@api_bp.get("/collaborators")
@relay_required
def collaborators():
    """Full collaborator list (including inactive ones so relays can drop them)."""
    rows = Collaborator.query.order_by(Collaborator.id).all()
    return jsonify(collaborators=[u.to_api() for u in rows])


@api_bp.get("/collaborators/<collaborator_id>/photo")
@relay_required
def collaborator_photo(collaborator_id):
    collaborator = db.session.get(Collaborator, collaborator_id)
    if not collaborator or not collaborator.photo_path:
        return jsonify(error="not_found"), 404
    return send_from_directory(current_app.config["PHOTOS_DIR"], collaborator.photo_path.split("/")[-1])


def _face_check(uuid):
    """Compare the snapshot with the collaborator's photo now if possible (else the background worker does)."""
    from .verify import engine, verify_checkin
    if not engine().ok:
        return
    try:
        c = Checkin.query.filter_by(uuid=uuid).first()
        verify_checkin(c)
        db.session.commit()
    except Exception:
        db.session.rollback()
        current_app.logger.exception("Face check of %s failed (retried later)", uuid)


def _parse_ts(value):
    ts = datetime.fromisoformat(str(value))
    if ts.tzinfo is None:
        raise ValueError("timestamp must include a UTC offset")
    return ts


def _snapshot(value):
    """Decoded JPEG bytes, or None when the relay sent none. Raises ValueError if it's not a JPEG."""
    if not value:
        return None
    data = base64.b64decode(str(value), validate=True)
    if len(data) > current_app.config["MAX_SNAPSHOT_BYTES"]:
        raise ValueError("snapshot too large")
    if not data.startswith(JPEG_MAGIC):
        raise ValueError("snapshot is not a JPEG image")
    return data


def _distance(value):
    if value is None:
        return None
    d = float(value)
    if not math.isfinite(d):
        raise ValueError("bad distance")
    return d


@api_bp.post("/checkins")
@relay_required
def push_checkins():
    """Body: {"checkins": [{uuid, seq, collaborator_id, direction, timestamp, status, reason,
    distance, timezone, snapshot_sha256, location {lat, lng, accuracy}, signature, snapshot (base64 jpeg)}]}

    Every check-in is signed by the relay when it is made (its private key never leaves it): one
    created or changed anywhere else (relay database edited, stolen relay token) is rejected
    ("bad_signature"). Check-ins are numbered by the relay: a missing number means some were
    deleted before they reached this server, and the next one is flagged "gap".

    Each check-in is stored, then its snapshot is compared with the collaborator's photo
    (server-side face check); a check-in without snapshot is flagged.

    The server never trusts the relay for what it can work out itself: the relay name comes from
    its token, the site time zone is the relay's (set on the Relays page, or pinned at its first
    check-in), and OK/KO is computed here from the time and the settings. A timestamp in the
    future is refused; one received long after it was made while the relay was connected is
    flagged "delayed".

    Idempotent: already known uuids are reported as accepted.
    Response: {"accepted": [uuid...], "rejected": [{uuid, error}...]}
    """
    payload = request.get_json(silent=True) or {}
    items = payload.get("checkins") or []
    if not isinstance(items, list):
        return jsonify(error="bad_request"), 400
    cfg = current_app.config
    relay = g.relay
    relay_pk = g.relay_public_key
    if relay.seq_key != relay_pk:  # new relay key (reinstalled relay): numbering starts again
        relay.seq_key, relay.last_seq = relay_pk, None
        db.session.commit()
    accepted, rejected = [], []

    for item in items[:100]:
        if not isinstance(item, dict):
            continue
        uuid = str(item.get("uuid", "")).strip().lower()[:36]
        try:
            if not UUID_RE.match(uuid):
                raise ValueError("bad uuid")
            if not verify_ed25519(relay_pk, str(item.get("signature") or ""),
                                  checkin_message(_signed_record(item, relay.instance_id))):
                raise ValueError("bad_signature")
            seq = item.get("seq")
            if not isinstance(seq, int) or isinstance(seq, bool) or seq < 1:
                raise ValueError("bad seq")
            if Checkin.query.filter_by(uuid=uuid).first():
                accepted.append(uuid)
                continue
            collaborator_id = str(item["collaborator_id"])
            if not db.session.get(Collaborator, collaborator_id):
                raise ValueError("unknown collaborator")
            direction = item["direction"]
            if direction not in ("IN", "OUT"):
                raise ValueError("bad direction")
            relay_status = item.get("status")
            if relay_status not in (None, "OK", "KO"):
                raise ValueError("bad status")

            now = utcnow()
            timestamp = _parse_ts(item["timestamp"])
            if timestamp - now > timedelta(seconds=cfg["CHECKIN_MAX_FUTURE_SECONDS"]):
                raise ValueError("timestamp in the future")

            # Site time zone: the relay's own, pinned on the main server (first check-in sets it)
            sent_tz = str(item.get("timezone") or "")[:64] or None
            if not relay.timezone and sent_tz and tz_from_name(sent_tz):
                relay.timezone = sent_tz
            tz_name = relay.timezone or sent_tz
            tz = tz_from_name(tz_name)
            local = timestamp.astimezone(tz) if tz else timestamp
            status, reason = evaluate(direction, local, effective_settings(relay))
            if relay_status and relay_status != status:
                current_app.logger.warning("Check-in %s: relay %s said %s, computed %s", uuid, relay.name,
                                           relay_status, status)

            time_check = None
            if (relay.online_since and timestamp > relay.online_since + timedelta(seconds=120)
                    and (now - timestamp).total_seconds() > cfg["CHECKIN_MAX_DELAY_SECONDS"]):
                time_check = "delayed"

            if relay.last_seq is not None and seq > relay.last_seq + 1:
                time_check = "gap"  # check-ins numbered last_seq+1 .. seq-1 never arrived
                current_app.logger.warning("Check-in %s: relay %s skipped numbers %d-%d (deleted on the relay?)",
                                           uuid, relay.name, relay.last_seq + 1, seq - 1)
            elif relay.last_seq is not None and seq <= relay.last_seq and Checkin.query.filter_by(
                    relay_id=relay.id, relay_seq=seq).first():
                time_check = "gap"  # number used twice: the relay's numbering was reset (data deleted)
                current_app.logger.warning("Check-in %s: relay %s reused number %d", uuid, relay.name, seq)

            # GPS location: never a reason to refuse a check-in, only flagged when outside the area
            loc = _location(item.get("location"))
            in_area, area_distance = area_check(relay, loc)
            if in_area == "outside":
                current_app.logger.warning("Check-in %s: %s m from the centre of relay %s's area (radius %s m)",
                                           uuid, area_distance, relay.name, relay.area_radius)

            snapshot = _snapshot(item.get("snapshot"))
            snapshot_path = sha = None
            if snapshot is not None and hashlib.sha256(snapshot).hexdigest() != item.get("snapshot_sha256"):
                raise ValueError("snapshot_mismatch")  # not the picture the relay signed
            if snapshot is not None:
                # the file name is the validated UUID: it can't leave the snapshots folder
                name = f"{uuid}.jpg"
                (cfg["SNAPSHOTS_DIR"] / name).write_bytes(snapshot)
                snapshot_path, sha = f"snapshots/{name}", hashlib.sha256(snapshot).hexdigest()

            db.session.add(
                Checkin(
                    uuid=uuid,
                    collaborator_id=collaborator_id,
                    relay_id=relay.id,
                    direction=direction,
                    timestamp=timestamp,
                    status=status,
                    reason=reason,
                    relay_status=relay_status if relay_status and relay_status != status else None,
                    distance=_distance(item.get("distance")),
                    snapshot_path=snapshot_path,
                    snapshot_sha256=sha,
                    time_check=time_check,
                    timezone=tz_name,
                    relay_name=relay.name,
                    relay_seq=seq,
                    latitude=loc[0] if loc else None,
                    longitude=loc[1] if loc else None,
                    location_accuracy=loc[2] if loc else None,
                    area_check=in_area,
                    area_distance=area_distance,
                )
            )
            relay.last_seq = max(relay.last_seq or 0, seq)
            db.session.commit()
            accepted.append(uuid)
            _face_check(uuid)
        except (KeyError, TypeError, ValueError, binascii.Error, IntegrityError) as exc:
            db.session.rollback()
            rejected.append({"uuid": uuid, "error": str(exc)[:200]})

    return jsonify(accepted=accepted, rejected=rejected)
